const fs = require('node:fs');

function apiLevel(value) {
  if (Number.isInteger(value) && value >= 10) return value;
  const match = /\((\d+)\)$/.exec(value);
  if (!match) throw new Error('Unsupported Lite API version: ' + value);
  return Number(match[1]);
}

function select(object, allowed) {
  const result = {};
  for (const key of allowed) {
    if (Object.prototype.hasOwnProperty.call(object, key)) result[key] = object[key];
  }
  return result;
}

// This is a COMPILED profile: resource IDs generated by restool are required
// by the Lite bundle parser, even though source configSchema_lite omits them.
// Adapt BEFORE HAP-to-BIN packaging and signing, never after signing.
function normalize(profile, compatible, target) {
  if (!profile.module.deviceType.includes('liteWearable')) {
    throw new Error('This adapter only accepts Lite Wearable profiles.');
  }
  const app = select(profile.app, ['bundleName', 'vendor', 'version', 'smartWindowSize', 'smartWindowDeviceType']);
  app.apiVersion = { compatible: apiLevel(compatible), target: apiLevel(target), releaseType: 'Release' };
  if (app.apiVersion.compatible > app.apiVersion.target) throw new Error('Invalid Lite API range.');
  const module = select(profile.module, [
    'description', 'abilities', 'js', 'reqPermissions', 'deviceType', 'distro',
    'reqCapabilities', 'metaData', 'resizeable', 'distroFilter'
  ]);
  module.abilities = profile.module.abilities.map(ability => select(ability, [
    'name', 'description', 'icon', 'type', 'label', 'visible', 'deviceCapability',
    'resizeable', 'srcLanguage', 'srcPath', 'metaData', 'skills',
    'iconId', 'labelId', 'descriptionId'
  ]));
  for (const ability of module.abilities) {
    for (const [field, id] of [['icon', 'iconId'], ['label', 'labelId'], ['description', 'descriptionId']]) {
      if (typeof ability[field] === 'string' && /^\$(media|string):/.test(ability[field]) &&
          (!Number.isInteger(ability[id]) || ability[id] <= 0)) {
        throw new Error('Compiled Lite resource reference ' + field + ' requires ' + id + '. Rebuild resources.');
      }
    }
  }
  const deviceConfig = {};
  for (const type of ['default', 'liteWearable', 'smartVision']) {
    if (profile.deviceConfig[type]) deviceConfig[type] = select(profile.deviceConfig[type], ['keepAlive']);
  }
  return { app, deviceConfig, module };
}

function normalizeFile(file, compatible, target) {
  const input = JSON.parse(fs.readFileSync(file, 'utf8'));
  const output = normalize(input, compatible, target);
  fs.writeFileSync(file, JSON.stringify(output, null, 2) + '\n', 'utf8');
  console.log('[techpie-lite] Packaged configuration uses API ' + output.app.apiVersion.target);
}

function readSdkRange(file) {
  const text = fs.readFileSync(file, 'utf8');
  function read(key) {
    const match = new RegExp('"' + key + '"\\s*:\\s*(?:"([^"]+)"|(\\d+))').exec(text);
    if (!match) throw new Error('Missing ' + key + ' in the build profile.');
    return match[1] || Number(match[2]);
  }
  return [read('compatibleSdkVersion'), read('targetSdkVersion')];
}

module.exports = { apiLevel, normalize, normalizeFile, readSdkRange };
